MOD = 1_000_000_007

def count_orderings(N, names):
    # Sort names lexicographically
    names.sort()

    # Group names by their longest common prefix
    prefix_groups = defaultdict(list)
    current_prefix = ""
    for name in names:
        if name.startswith(current_prefix):
            prefix_groups[current_prefix].append(name)
        else:
            # Find the longest common prefix
            for i in range(len(current_prefix)):
